package com.bank.hpp.controller;

import com.bank.hpp.model.AccountType;
import com.bank.hpp.service.TransferService;
import org.springframework.web.bind.annotation.*;
import java.math.BigDecimal;

@RestController
@RequestMapping("/api/v1/transfers")
public class TransferController {

    private final TransferService transferService;

    public TransferController(TransferService transferService) {
        this.transferService = transferService;
    }

    // accountType binds to a strict enum. A polluted or invalid value fails
    // binding and returns 400 before any business logic runs.
    @PostMapping
    public String transfer(@RequestParam String from,
                           @RequestParam AccountType accountType,
                           @RequestParam BigDecimal amount) {
        return transferService.transfer(from, accountType, amount);
    }
}
