// ─── File: src/main/java/com/bank/hpp/service/TransferService.java ───
package com.bank.hpp.service;

import com.bank.hpp.model.AccountType;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;

@Service
public class TransferService {

    private static final Logger log = LoggerFactory.getLogger(TransferService.class);
    private static final BigDecimal SAVINGS_LIMIT = new BigDecimal("100000");
    private static final BigDecimal CURRENT_LIMIT = new BigDecimal("5000000");

    public String transfer(String from, AccountType accountType, BigDecimal amount) {
        // The limit is driven by a SINGLE, unambiguous accountType value.
        BigDecimal limit = accountType == AccountType.CURRENT ? CURRENT_LIMIT : SAVINGS_LIMIT;
        if (amount.compareTo(limit) > 0) {
            log.warn("Transfer rejected: {} {} exceeds limit {}", accountType, amount, limit);
            return "REJECTED: exceeds " + accountType + " limit";
        }
        log.info("Transfer approved: {} from {} as {}", amount, from, accountType);
        return "APPROVED";
    }
}
```

