package com.bank.hpp.exception;

import org.springframework.http.*;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.method.annotation.MethodArgumentTypeMismatchException;

@RestControllerAdvice
public class GlobalExceptionHandler {

    // Triggered when accountType cannot bind to the enum (bad or polluted value).
    @ExceptionHandler(MethodArgumentTypeMismatchException.class)
    public ResponseEntity<String> handleBadParam(MethodArgumentTypeMismatchException ex) {
        return ResponseEntity.badRequest()
                .body("{\"error\":\"INVALID_PARAMETER\",\"field\":\"" + ex.getName() + "\"}");
    }
}
